#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using MVZ2.Modding;
using MVZ2.Sprites;
using MVZ2Logic.Options;
using MVZ2Logic.Resources;
using MVZ2Logic.UI;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.AddressableAssets;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        public SpriteVariantContext GetSpriteVariantContext()
        {
            return new SpriteVariantContext()
            {
                censored = !Main.OptionsManager.HasBloodAndGore(),
                languageCode = Main.LanguageManager.GetCurrentLanguage(),
            };
        }

        #region Provider
        public void AddSpriteProvider(ISpriteProvider provider)
        {
            spriteResolver.AddProvider(provider);
        }
        public void RemoveSpriteProvider(ISpriteProvider provider)
        {
            spriteResolver.RemoveProvider(provider);
        }
        #endregion

        public void RegisterSprite(SpriteReference spriteReference, Sprite sprite)
        {
            var key = new SpriteLookupKey(spriteReference);
            RegisterSprite(key, sprite);
        }

        public void RegisterSprite(SpriteLookupKey key, Sprite sprite)
        {
            baseGameSprites.Register(key, sprite);
        }

        #region 获取Sprite
        public Sprite? GetSprite(SpriteReference? spriteRef)
        {
            if (!SpriteReference.IsValid(spriteRef))
                return null;
            var spriteLookupKey = new SpriteLookupKey(spriteRef);
            return baseGameSprites.TryGet(spriteLookupKey, out var spr) ? spr : null;
        }
        #endregion

        #region 获取最终贴图
        public Sprite GetFinalSprite(Sprite sprite)
        {
            var spriteRef = GetSpriteReference(sprite);
            return GetFinalSprite(spriteRef) ?? sprite;
        }
        public Sprite GetFinalSprite(Sprite sprite, SpriteVariantContext args)
        {
            var spriteRef = GetSpriteReference(sprite);
            return GetFinalSprite(spriteRef, args) ?? sprite;
        }
        public Sprite? GetFinalSprite(SpriteReference? spriteRef)
        {
            return GetFinalSprite(spriteRef, GetSpriteVariantContext());
        }
        public Sprite? GetFinalSprite(SpriteReference? spriteRef, SpriteVariantContext context)
        {
            if (!SpriteReference.IsValid(spriteRef))
                return null;
            return spriteResolver.Resolve(spriteRef, context);
        }
        #endregion

        #region SpriteReference
        public SpriteReference? GetSpriteReference(Sprite sprite)
        {
            return baseGameSprites.GetKey(sprite)?.reference;
        }
        #endregion

        #region 获取默认贴图
        public Sprite GetDefaultSprite()
        {
            return defaultSprite;
        }
        public Sprite GetDefaultSpriteClone()
        {
            return Instantiate(defaultSprite);
        }
        #endregion

        #region 初始化
        private void Init_Sprites()
        {
            if (Application.isEditor)
            {
                backgroundTex = GenerateSpriteBackgroundTexture(MAX_BACKGROUND_TEX_WIDTH, MAX_BACKGROUND_TEX_HEIGHT);
            }
            spriteResolver.AddProvider(baseGameSprites);
        }
        private void ClearResources_Sprites()
        {
            baseGameSprites.Clear();
        }
        #endregion

        #region SpriteManifest
        private async Task LoadInitSpriteManifests(string modNamespace)
        {
            var modResource = GetModResource(modNamespace);
            if (modResource == null)
                return;
            var resources = await LoadLabeledResources<SpriteManifest>(modNamespace, Addressables.MergeMode.Intersection, "Init", "SpriteManifest");
            foreach (var (path, manifest) in resources)
            {
                LoadSpriteManifest(modNamespace, modResource, manifest);
            }
        }
        private async Task LoadMainSpriteManifests(string modNamespace, TaskProgress progress)
        {
            var modResource = GetModResource(modNamespace);
            if (modResource == null)
                return;
            var resources = await LoadLabeledResources<SpriteManifest>(modNamespace, Addressables.MergeMode.Intersection, progress, "Main", "SpriteManifest");
            foreach (var (id, res) in resources)
            {
                LoadSpriteManifest(modNamespace, modResource, res);
            }
        }
        private void LoadSpriteManifest(string modNamespace, ModResource modResource, SpriteManifest manifest)
        {
            if (manifest.spriteEntries != null)
            {
                foreach (var entry in manifest.spriteEntries)
                {
                    if (string.IsNullOrEmpty(entry.name))
                        continue;
                    var sprite = entry.sprite;
                    if (!sprite.Exists())
                        continue;
                    var id = new NamespaceID(modNamespace, entry.name);
                    var spriteRef = new SpriteReference(id, entry.index);
                    var spriteLookupKey = new SpriteLookupKey(spriteRef, entry.tags.ToArray());
                    RegisterSprite(spriteLookupKey, sprite);
                }
            }
        }
        #endregion

        [Header("Sprites")]
        [SerializeField]
        private Sprite defaultSprite = null!;
        private SpriteResolver spriteResolver = new SpriteResolver();
        private SpriteDatabase baseGameSprites = new SpriteDatabase();
    }
}
